+/**
+ * Disclosure widget — FAQ
+ *
+ * Each `.example` contains:
+ *   button.disclosure-btn[aria-expanded][aria-controls]
+ *   div.details[id]
+ *
+ * Collapsed by default; toggled on click / Space / Enter.
+ */
+(function () {
+  "use strict";
+
+  function initDisclosures() {
+    document.querySelectorAll(".disclosure-btn").forEach(function (btn) {
+      var panelId = btn.getAttribute("aria-controls");
+      var panel = document.getElementById(panelId);
+      if (!panel) return;
+
+      btn.addEventListener("click", function () {
+        var expanded = btn.getAttribute("aria-expanded") === "true";
+        toggle(btn, panel, !expanded);
+      });
+    });
+  }
+
+  function toggle(btn, panel, open) {
+    btn.setAttribute("aria-expanded", String(open));
+
+    if (open) {
+      panel.setAttribute("data-open", "true");
+      // Set exact height so the CSS transition has a concrete target
+      var inner = panel.querySelector(".details-inner");
+      if (inner) {
+        panel.style.maxHeight = inner.scrollHeight + "px";
+      }
+    } else {
+      // Collapse: first set explicit height, then snap to 0 on next frame
+      panel.style.maxHeight = panel.scrollHeight + "px";
+      // Force reflow so the browser registers the explicit height before transition
+      panel.getBoundingClientRect(); // eslint-disable-line no-unused-expressions
+      panel.style.maxHeight = "0px";
+      panel.removeAttribute("data-open");
+    }
+  }
+
+  if (document.readyState === "loading") {
+    document.addEventListener("DOMContentLoaded", initDisclosures);
+  } else {
+    initDisclosures();
+  }
+})();
+
')

