+/* ── Reset & base ── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --bg:           #0f1117;
+  --surface:      #1a1d27;
+  --surface-hover:#21253a;
+  --border:       #2e3250;
+  --accent:       #7c6af7;
+  --accent-light: #a89cf9;
+  --text:         #e2e4f0;
+  --text-muted:   #8b90aa;
+  --radius:       10px;
+  --transition:   220ms ease;
+}
+
+body {
+  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
+  background: var(--bg);
+  color: var(--text);
+  line-height: 1.7;
+  min-height: 100vh;
+  padding: 2rem 1rem 4rem;
+}
+
+/* ── Skip link ── */
+.skip-link {
+  position: absolute;
+  top: -999px;
+  left: 1rem;
+  padding: .5rem 1rem;
+  background: var(--accent);
+  color: #fff;
+  border-radius: var(--radius);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+}
+.skip-link:focus { top: 1rem; }
+
+/* ── Page chrome ── */
+.page-header {
+  text-align: center;
+  margin-bottom: 2.5rem;
+}
+
+.page-header h1 {
+  font-size: clamp(1.8rem, 5vw, 3rem);
+  font-weight: 800;
+  letter-spacing: -.02em;
+  background: linear-gradient(135deg, var(--accent-light) 0%, #c4b5fd 60%, var(--text) 100%);
+  -webkit-background-clip: text;
+  -webkit-text-fill-color: transparent;
+  background-clip: text;
+}
+
+.page-header p {
+  margin-top: .5rem;
+  color: var(--text-muted);
+  font-size: 1.05rem;
+}
+
+/* ── FAQ container ── */
+.faq-list {
+  max-width: 720px;
+  margin: 0 auto;
+  display: flex;
+  flex-direction: column;
+  gap: 1rem;
+}
+
+/* ── Individual item ── */
+.example {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  transition: border-color var(--transition), box-shadow var(--transition);
+}
+
+.example:has(.disclosure-btn[aria-expanded="true"]) {
+  border-color: var(--accent);
+  box-shadow: 0 0 0 1px var(--accent), 0 4px 24px rgba(124, 106, 247, .15);
+}
+
+/* ── Toggle button ── */
+.disclosure-btn {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  width: 100%;
+  padding: 1.1rem 1.4rem;
+  background: transparent;
+  border: none;
+  color: var(--text);
+  font-size: 1rem;
+  font-weight: 600;
+  text-align: left;
+  cursor: pointer;
+  gap: 1rem;
+  transition: background var(--transition), color var(--transition);
+}
+
+.disclosure-btn:hover {
+  background: var(--surface-hover);
+  color: var(--accent-light);
+}
+
+.disclosure-btn:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: -2px;
+  border-radius: calc(var(--radius) - 1px);
+}
+
+/* ── Chevron icon ── */
+.chevron {
+  flex-shrink: 0;
+  width: 20px;
+  height: 20px;
+  fill: none;
+  stroke: var(--accent);
+  stroke-width: 2.5;
+  stroke-linecap: round;
+  stroke-linejoin: round;
+  transition: transform var(--transition);
+  aria-hidden: true;
+}
+
+.disclosure-btn[aria-expanded="true"] .chevron {
+  transform: rotate(180deg);
+}
+
+/* ── Answer panel ── */
+.details {
+  overflow: hidden;
+  max-height: 0;
+  transition: max-height 300ms cubic-bezier(.4, 0, .2, 1);
+}
+
+.details[data-open="true"] {
+  max-height: 600px; /* generous cap — JS sets exact value */
+}
+
+.details-inner {
+  padding: .25rem 1.4rem 1.25rem;
+  color: var(--text-muted);
+  border-top: 1px solid var(--border);
+}
+
+.details-inner p { margin-top: .75rem; }
+.details-inner p:first-child { margin-top: 0; }
+
+/* ── Footer ── */
+.page-footer {
+  text-align: center;
+  margin-top: 3rem;
+  color: var(--text-muted);
+  font-size: .85rem;
+}
+
+/* ── Reflow (320 px) ── */
+@media (max-width: 400px) {
+  .disclosure-btn { padding: .9rem 1rem; font-size: .95rem; }
+  .details-inner  { padding: .25rem 1rem 1rem; }
+}
+
+/* ── Forced-colors ── */
+@media (forced-colors: active) {
+  .example { border: 1px solid ButtonBorder; }
+  .disclosure-btn { color: ButtonText; }
+  .disclosure-btn:hover { background: Highlight; color: HighlightText; }
+  .chevron { stroke: ButtonText; }
+  .details-inner { border-top: 1px solid ButtonBorder; color: CanvasText; }
+}
+
+/* ── Reduced motion ── */
+@media (prefers-reduced-motion: reduce) {
+  .details,
+  .chevron,
+  .disclosure-btn,
+  .example { transition: none; }
+}
+
